import{_ as e,o as a,c as l,am as s}from"./chunks/framework.CiF4W93w.js";const u=JSON.parse('{"title":"Redis入门_Redis实战篇","description":"","frontmatter":{"title":"Redis入门_Redis实战篇","excerpt":"Redis入门_Redis实战篇，主要是总结一下别人的一篇博客内容，向对方学习","date":"2023-12-25 16:47:48","updated":"2023-12-25 16:47:48"},"headers":[],"relativePath":"中间件/技术栈 Redis/Redis入门_Redis实战篇/index.md","filePath":"中间件/技术栈 Redis/Redis入门_Redis实战篇/index.md","lastUpdated":null}'),n={name:"中间件/技术栈 Redis/Redis入门_Redis实战篇/index.md"};function t(o,i,r,p,d,h){return a(),l("div",null,[...i[0]||(i[0]=[s(`<p>参考： <a href="https://cyborg2077.github.io/2022/10/22/RedisPractice/" target="_blank" rel="noreferrer">https://cyborg2077.github.io/2022/10/22/RedisPractice/</a></p><p>视频内容： <a href="https://www.bilibili.com/video/BV1cr4y1671t/" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1cr4y1671t/</a></p><p>结合文章一起看一下</p><p>后续再跟进一下，这里记录的其实还挺好的，需要花费一段时间看一下</p><h3 id="短信登录" tabindex="-1">短信登录 <a class="header-anchor" href="#短信登录" aria-label="Permalink to &quot;短信登录&quot;">​</a></h3><h4 id="session-方案" tabindex="-1">Session 方案 <a class="header-anchor" href="#session-方案" aria-label="Permalink to &quot;Session 方案&quot;">​</a></h4><ul><li>1、单体的话进行登录校验的话，一般会使用 session 会话的方式，</li></ul><p>大体的流程</p><p>这里使用了 用户信息存放到 ThreadLocal 的操作，</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240508223035.png" alt="image.png"></p><p>用户信息返回的时候一般会使用 vo 对象，将 User 和 UserVo 对象做一个转换，避免将敏感信息泄漏</p><p>使用 共享 session 会存在的问题</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240508223449.png" alt="image.png"></p><h4 id="redis-方案" tabindex="-1">Redis 方案 <a class="header-anchor" href="#redis-方案" aria-label="Permalink to &quot;Redis 方案&quot;">​</a></h4><p>Redis 替代 session 的业务流程</p><ul><li>这里存入登录用户信息，一般会使用 String 或者 Hash 的结构（存放 session 信息或者 jwt 信息）</li><li>这里采用的是 hash 结构 <ul><li>考虑一下 key 的组成 <ul><li>1、不建议使用 Phone 等敏感信息</li><li>2、保证 key 是唯一性</li><li>3、key 方便携带</li></ul></li></ul></li></ul><p>访问流程</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240508223918.png" alt="image.png"></p><p>代码内容</p><ul><li>1、生成唯一 token，前缀 + token 作为 key</li><li>2、用户信息作为 hash 的 value</li><li>3、存放 用户信息 到 redis 中</li><li>4、删除验证码信息</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240508224323.png" alt="image.png"></p><h4 id="登录刷新问题" tabindex="-1">登录刷新问题 <a class="header-anchor" href="#登录刷新问题" aria-label="Permalink to &quot;登录刷新问题&quot;">​</a></h4><ul><li>问题 <ul><li>如果用户没有任何操作30分钟，则token会消失，用户需要重新登录</li></ul></li><li>解决 <ul><li>用户每次请求都进行一次拦截，进行刷新令牌的操作</li></ul></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240508224735.png" alt="image.png"></p><h3 id="查询缓存" tabindex="-1">查询缓存 <a class="header-anchor" href="#查询缓存" aria-label="Permalink to &quot;查询缓存&quot;">​</a></h3><p>缓存方式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//本地用高并发</span></span>
<span class="line"><span>Static final ConcurrentHashMap&lt;K,V&gt; map = new ConcurrentHashMap&lt;&gt;();</span></span>
<span class="line"><span>//Redis 缓存</span></span>
<span class="line"><span>static final Cache&lt;K,V&gt; USER_CACHE = CacheBuilder.newBuilder().build();</span></span>
<span class="line"><span>//本地缓存</span></span>
<span class="line"><span>Static final Map&lt;K,V&gt; map =  new HashMap();</span></span></code></pre></div><ul><li>由于其被<code>static</code>修饰，所以随着类的加载而加载到内存之中，作为本地缓存，由于其又被<code>final</code>修饰，所以其引用之间的关系是固定的，不能改变，因此不用担心复制导致缓存失败</li></ul><p>常用缓存</p><ul><li>浏览器缓存</li><li>应用层缓存</li><li>数据库缓存</li><li>CPU 缓存</li></ul><p>缓存常见问题</p><ul><li>缓存穿透 <ul><li>⽤户频繁使⽤缓存和数据库中不存在的数据进⾏访 问，导致流量直接打到数据库，导致数据库挂了</li><li>解决方式 <ul><li>接⼝层增加校验</li><li>如果缓存中不存在该值，就缓存空值到缓存中（空对象缓存）</li><li>使⽤布隆过滤器，布隆过滤器是⼀个位图，如果它说不存在就 ⼀定不存在，如果说存在只能是可能存在，可以将可能存在的 key放⼊bitmap进⾏过滤</li><li>热点数据限流</li></ul></li></ul></li><li>缓存击穿 <ul><li>⼤量⽤户访问某个key时，这个key刚好失效，导致流 量直接打到数据库，导致数据库挂了</li><li>解决方式 <ul><li>设置热点数据永不过期</li><li>加互斥锁</li><li>逻辑过期</li></ul></li></ul></li><li>缓存雪崩 <ul><li>由于⼤量的key在同⼀时间失效，导致流量直接打到数 据库，导致数据库挂了</li><li>解决方式 <ul><li>可以将key的过期时间设置随机值，避免同⼀时间过期</li><li>给每⼀个缓存数据加⼀个缓存标记来记录缓存是否失效，如果 失效就更新</li><li>并发量不多的时候可以采⽤加锁排队</li><li>限流</li><li>多级缓存（浏览器缓存 → Nginx 缓存 → Redis 缓存 → JVM 进程缓存 → 数据库）</li></ul></li></ul></li></ul><p>逻辑过期方案</p><ul><li>线程读取过程中不需要等待，性能好，有一个额外的线程持有锁去进行重构缓存数据，但是在重构数据完成之前，其他线程只能返回脏数据，且实现起来比较麻烦</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240508230835.png" alt="image.png"></p><h4 id="封装-redis-工具类" tabindex="-1">封装 Redis 工具类 <a class="header-anchor" href="#封装-redis-工具类" aria-label="Permalink to &quot;封装 Redis 工具类&quot;">​</a></h4><p>大概知道一下工具类常见方法有哪些</p><p>to be contined....</p><h3 id="优惠券秒杀" tabindex="-1">优惠券秒杀 <a class="header-anchor" href="#优惠券秒杀" aria-label="Permalink to &quot;优惠券秒杀&quot;">​</a></h3><h3 id="分布式锁" tabindex="-1">分布式锁 <a class="header-anchor" href="#分布式锁" aria-label="Permalink to &quot;分布式锁&quot;">​</a></h3><p>分布式锁</p><p>分布式锁</p><ul><li>满足分布式系统或集群模式下多线程课件并且可以互斥的锁</li><li>分布式锁的核心思想就是让大家共用同一把锁，那么我们就能锁住线程，不让线程进行，让程序串行执行，这就是分布式锁的核心思路</li></ul><p>常见的分布式锁有三种</p><ul><li>MySQL：MySQL本身就带有锁机制，但是由于MySQL的性能一般，所以采用分布式锁的情况下，使用MySQL作为分布式锁比较少见 <ul><li>（例如基于 CAS 的乐观锁）</li></ul></li><li>Redis：Redis作为分布式锁是非常常见的一种使用方式，现在企业级开发中基本都是用Redis或者Zookeeper作为分布式锁，利用<code>SETNX</code>这个方法，如果插入Key成功，则表示获得到了锁，如果有人插入成功，那么其他人就回插入失败，无法获取到锁，利用这套逻辑完成<code>互斥</code>，从而实现分布式锁</li><li>Zookeeper：Zookeeper也是企业级开发中较好的一种实现分布式锁的方案（利用节点的唯一性和有序性实现互斥）</li></ul><p>其他方案后面看</p><p>Redis 方案</p><ul><li>加锁 setnx</li><li>释放锁 del</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240509151246.png" alt="image.png"></p><h3 id="分布式锁-redisson" tabindex="-1">分布式锁-Redisson <a class="header-anchor" href="#分布式锁-redisson" aria-label="Permalink to &quot;分布式锁-Redisson&quot;">​</a></h3><h3 id="秒杀优化" tabindex="-1">秒杀优化 <a class="header-anchor" href="#秒杀优化" aria-label="Permalink to &quot;秒杀优化&quot;">​</a></h3><h3 id="redis-消息队列" tabindex="-1">Redis 消息队列 <a class="header-anchor" href="#redis-消息队列" aria-label="Permalink to &quot;Redis 消息队列&quot;">​</a></h3><h3 id="达人探店" tabindex="-1">达人探店 <a class="header-anchor" href="#达人探店" aria-label="Permalink to &quot;达人探店&quot;">​</a></h3><h3 id="好友关注" tabindex="-1">好友关注 <a class="header-anchor" href="#好友关注" aria-label="Permalink to &quot;好友关注&quot;">​</a></h3><h3 id="附近商户" tabindex="-1">附近商户 <a class="header-anchor" href="#附近商户" aria-label="Permalink to &quot;附近商户&quot;">​</a></h3><h3 id="用户签到" tabindex="-1">用户签到 <a class="header-anchor" href="#用户签到" aria-label="Permalink to &quot;用户签到&quot;">​</a></h3><h3 id="uv-统计" tabindex="-1">UV 统计 <a class="header-anchor" href="#uv-统计" aria-label="Permalink to &quot;UV 统计&quot;">​</a></h3>`,57)])])}const b=e(n,[["render",t]]);export{u as __pageData,b as default};
